// Category A compound component — picker behavior from React Aria, swatch look from Sando.
import {
  ColorSwatchPicker as AriaColorSwatchPicker,
  ColorSwatchPickerItem as AriaColorSwatchPickerItem,
} from "react-aria-components";
import type {
  ColorSwatchPickerProps as AriaColorSwatchPickerProps,
  ColorSwatchPickerItemProps as AriaColorSwatchPickerItemProps,
} from "react-aria-components";
import type { Ref } from "react";
import { ColorSwatch } from "./ColorSwatch";
import "./ColorSwatchPicker.css";

export interface ColorSwatchPickerProps
  extends Omit<AriaColorSwatchPickerProps, "className"> {
  /** Additional class. sd-color-swatch-picker is always preserved. */
  className?: string;
  /** Passed to the underlying picker DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export interface ColorSwatchPickerItemProps
  extends Omit<AriaColorSwatchPickerItemProps, "className" | "children"> {
  /** Additional class. sd-color-swatch-picker__item is always preserved. */
  className?: string;
  /** Passed to the underlying item DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ColorSwatchPicker({
  className,
  ref,
  ...props
}: ColorSwatchPickerProps) {
  return (
    <AriaColorSwatchPicker
      {...props}
      ref={ref}
      className={
        className ? `sd-color-swatch-picker ${className}` : "sd-color-swatch-picker"
      }
    />
  );
}

export function ColorSwatchPickerItem({
  color,
  className,
  ref,
  ...props
}: ColorSwatchPickerItemProps) {
  return (
    <AriaColorSwatchPickerItem
      {...props}
      ref={ref}
      color={color}
      className={
        className
          ? `sd-color-swatch-picker__item ${className}`
          : "sd-color-swatch-picker__item"
      }
    >
      <ColorSwatch className="sd-color-swatch-picker__swatch" />
    </AriaColorSwatchPickerItem>
  );
}

.sd-color-swatch-picker {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sd-color-swatch-picker-gap);
}
.sd-color-swatch-picker[data-layout="stack"] {
  flex-direction: column;
  flex-wrap: nowrap;
}

.sd-color-swatch-picker__item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* The item declares no size and hugs its swatch: its box is derived from the swatch plus its own
     padding and border. A declared size smaller than that sum squeezes the swatch inline and lets it
     overflow on the block axis, a tall pill in every brand. Shrinking the padding or the swatch is
     refused by their own tokens (`item.padding`: the ring is the item's box-shadow and uses none of
     it; `swatch.size`: the swatch keeps the rung its box needs), and the sum is off the Sys `size`
     scale (44 or 42 by brand against 16·24·32·40·48), so a literal would add an off-scale number per
     brand. Deriving it removes both.
     `flex: none` keeps the item from shrinking in its row (`.sd-avatargroup__avatar`'s reason), and
     `align-self: start` keeps it from stretching on the cross axis. Both are needed: `flex` governs
     the main axis only, so in the `[data-layout="stack"]` column container the default
     `align-items: stretch` would widen the item to the whole row. */
  flex: none;
  align-self: start;
  padding: var(--sd-color-swatch-picker-item-padding);
  background: var(--sd-color-swatch-picker-item-background);
  border: var(--sd-color-swatch-picker-item-border-width) solid var(--sd-color-swatch-picker-item-border);
  border-radius: var(--sd-color-swatch-picker-item-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  outline: none;
  cursor: pointer;
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-color-swatch-picker__item[data-hovered] {
  border-color: var(--sd-color-swatch-picker-item-border-hover);
}
/* Focus paints the ring only and leaves the border alone. This library shows selection with
   background and border and focus with box-shadow (GridList · ListBox · TagGroup · Table · Tabs), so
   the two use different properties and never collide. A focus border here would not separate them:
   `item.border.focus` is `color.border.focus` and selected is `color.border.accent`, the same value
   in every brand, so a focused selected item would show nothing that points at the focus. Without
   it, a plain focused item is the base border plus the ring, a selected one the accent border plus
   the halo. */
.sd-color-swatch-picker__item[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-color-swatch-picker__item[data-selected] {
  border-color: var(--sd-color-swatch-picker-item-border-selected);
  box-shadow: var(--sd-color-swatch-picker-item-shadow-selected);
}
/* selected 가 포커스되면 링과 halo 를 합성한다 — `box-shadow` 는 단일 속성이라 뒤에 오는
   selected 규칙이 링을 통째로 대체했고, React Aria 는 두 속성을 동시에 내보내므로 키보드가
   착지하는 바로 그 아이템에서 링이 사라졌다(WCAG 2.4.7). 순서는 SegmentedControl 과 같다:
   링을 먼저 두어 위에 칠하고, 컴포넌트 자신의 selected 그림자를 뒤에 둔다. */
.sd-color-swatch-picker__item[data-selected][data-focus-visible] {
  box-shadow:
    0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent),
    var(--sd-color-swatch-picker-item-shadow-selected);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-color-swatch-picker__item[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-color-swatch-picker__swatch {
  /* NO width/height here. The nested `ColorSwatch` defaults to `size="medium"`, and
     `.sd-color-swatch[data-size="medium"]` is (0,2,0) against this class's (0,1,0), so the
     standalone token wins and a size declared here would be dead. `radius` is the opposite case and
     stays: both rules are (0,1,0), so source order decides and this stylesheet is later.
     The swatch is therefore identical to a standalone `ColorSwatch` at size `medium`. */
  border-radius: var(--sd-color-swatch-picker-swatch-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  forced-color-adjust: none;
}
